'use strict';
(() => {
const chapters=Course.chapters;
// Resolve assets beside app.js so both the repository root and /dist/ work.
const assetBase=new URL('.',document.currentScript.src);
const assetUrl=relative=>new URL(relative,assetBase).href;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='web-notes-01076119-v1';
let storageAvailable=true;
let state={read:[],best:{},attempts:{},fullResults:{},last:1,quizRevision:Course.revision};
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){state={...state,...raw,quizRevision:raw.quizRevision};if(!Array.isArray(state.read))state.read=[];for(const k of ['best','attempts'])if(!state[k]||typeof state[k]!=='object')state[k]={};}}catch{storageAvailable=false;}
// Preserve old quiz data separately because questions 17-20 now use multiple answers.
let quizUpdated=false;
if(state.quizRevision!==Course.revision){
 state.previousQuiz={revision:state.quizRevision||'original',best:state.best,attempts:state.attempts};
 state.best={};state.attempts={};state.fullResults={};state.quizRevision=Course.revision;quizUpdated=true;
}
if(!state.fullResults||typeof state.fullResults!=='object')state.fullResults={};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;document.querySelector('.storage-warning')?.removeAttribute('hidden');}}
const paths={home:'<path d="m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9"/>',print:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6zM17 12h1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4L20 5"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.check}</svg>`;
const refs={
 1:[['MDN · HTTP status codes','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status']],
 2:[['MDN · script / defer','https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/script']],
 3:[['MDN · CSS cascade','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Cascade/Introduction']],
 4:[['MDN · Math.random และสูตรสุ่มจำนวนเต็ม','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Math/random']],
 9:[['Node.js · ECMAScript modules','https://nodejs.org/api/esm.html']],
 10:[['MDN · Using Fetch','https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch'],['MDN · Closures','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures'],['React · Updating objects in state','https://react.dev/learn/updating-objects-in-state']]
};
const root=document.getElementById('app');
let route={page:'chapter',id:1,tab:'lesson'};
let observer;
let incompleteConfirmed=false;
let toastTimer;
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3000);}
function sourceHTML(c){
 const links=[...(refs[c.id]||[]),...(c.refs||[])];
 return `<footer class="sources"><h3>ที่มาของบทนี้</h3><p class="source-badge">${escape(c.basis)}</p>${c.sources.length?`<ul>${c.sources.map(([file,pages])=>`<li><a href="${assetUrl('sources/'+encodeURIComponent(file))}" target="_blank" rel="noopener">${escape(file)}</a> · หน้า ${pages}</li>`).join('')}</ul>`:''}${links.length?`<p>เอกสารทางการ / แหล่งตรวจสอบ · ตรวจเมื่อ ${Course.reviewed}</p><ul>${links.map(([label,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${escape(label)}</a></li>`).join('')}</ul>`:''}<p>${c.id>10?'บทเสริมเขียนตามหัวข้อใน Scope_2026A และเอกสารทางการ ยังไม่ใช่ document เฉพาะที่อาจารย์จะส่งภายหลัง':'สรุปจาก PDF พร้อมคำอธิบายเสริมที่ระบุในบท'} · แบบฝึกเขียนขึ้นใหม่ ไม่ใช่ข้อสอบจริง</p></footer>`;
}
function progressHTML(){const n=state.read.filter(x=>chapters.some(c=>c.id===x)).length;return `<p><span>ความคืบหน้าการอ่าน</span><span>${n} / ${chapters.length}</span></p><progress value="${n}" max="${chapters.length}" aria-label="อ่านแล้ว ${n} จาก ${chapters.length} บท"></progress><a href="#/overview">เช็กขอบเขตสอบและคะแนน</a>`;}
function navHTML(){return `<a href="#/overview" class="nav-link ${route.page==='overview'?'active':''}" ${route.page==='overview'?'aria-current="page"':''}>${icon('home')}<span>ภาพรวมวิชา</span></a>${chapters.map(c=>`<a href="#/chapter/${c.id}/lesson" class="nav-link ${route.page==='chapter'&&route.id===c.id?'active':''}" ${route.page==='chapter'&&route.id===c.id?'aria-current="page"':''}><span class="nav-number ${state.read.includes(c.id)?'done':''}">${state.read.includes(c.id)?'✓':c.id}</span><span>${c.title}</span></a>`).join('')}`;}
function shell(){root.innerHTML=`<button class="mobile-scrim" aria-label="ปิดสารบัญ" tabindex="-1"></button><aside class="sidebar" aria-label="สารบัญบทเรียน"><button class="close-menu" aria-label="ปิดสารบัญ">×</button><a class="brand" href="#/overview"><img class="brand-mark" src="${assetUrl('favicon.svg')}" alt=""><div><strong>Web Notes</strong><span>01076119</span><span class="course-name">WEB APPLICATION DEVELOPMENT</span></div></a><nav id="nav">${navHTML()}</nav><div class="nav-footer">${progressHTML()}</div></aside><div class="workspace"><header class="topbar"><button class="menu-btn" aria-label="เปิดสารบัญ" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb" id="breadcrumb"></div><div class="search-wrap"><span class="search-icon">${icon('search')}</span><input id="search" class="search-input" type="search" placeholder="ค้นหาเนื้อหา…" aria-label="ค้นหาเนื้อหาบทเรียน" aria-controls="search-results" autocomplete="off"><div id="search-results" class="search-results" role="region" aria-label="ผลการค้นหา" hidden></div></div></header><div class="storage-warning" ${storageAvailable?'hidden':''}>เบราว์เซอร์ไม่อนุญาตให้บันทึกข้อมูล ความคืบหน้าครั้งนี้จะอยู่จนกว่าจะปิดหรือโหลดหน้าใหม่</div><div class="main-layout"><main id="main" class="reader" tabindex="-1"></main><aside id="toc" class="toc" aria-label="ทางลัดในหน้านี้"></aside></div></div>`;
 document.querySelector('.menu-btn').addEventListener('click',()=>menu(true));document.querySelector('.close-menu').addEventListener('click',()=>menu(false));document.querySelector('.mobile-scrim').addEventListener('click',()=>menu(false));
 document.getElementById('search').addEventListener('input',search);
 document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))document.getElementById('search-results').hidden=true;});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu(false);document.getElementById('search-results').hidden=true;}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('search').focus();}});
}
function menu(open){document.querySelector('.sidebar').classList.toggle('open',open);document.querySelector('.mobile-scrim').classList.toggle('open',open);document.querySelector('.menu-btn').setAttribute('aria-expanded',String(open));if(open)document.querySelector('.close-menu').focus();else if(document.activeElement?.closest('.sidebar'))document.querySelector('.menu-btn').focus();}
function parseRoute(){const parts=location.hash.slice(1).split('/').filter(Boolean);if(parts[0]==='overview')return {page:'overview'};const id=Number(parts[1]);return {page:'chapter',id:chapters.some(c=>c.id===id)?id:1,tab:['lesson','tips','quiz'].includes(parts[2])?parts[2]:'lesson'};}
function render(){observer?.disconnect();route=parseRoute();incompleteConfirmed=false;menu(false);document.getElementById('nav').innerHTML=navHTML();document.querySelector('.nav-footer').innerHTML=progressHTML();document.getElementById('search-results').hidden=true;document.getElementById('search').value='';const main=document.getElementById('main');
 if(route.page==='overview'){document.title='ภาพรวมวิชา · Web Notes 01076119';document.getElementById('breadcrumb').textContent='01076119 / ภาพรวมวิชา';main.innerHTML=overview();document.getElementById('toc').innerHTML=`<h3>ในหน้านี้</h3><a href="#" data-anchor="readiness">ประเมินความพร้อม</a><a href="#" data-anchor="scope-map">เทียบ Scope 24 หัวข้อ</a><a href="#" data-anchor="chapters">บทเรียน ${chapters.length} บท</a><a href="#" data-anchor="course-scope">วิธีใช้และข้อจำกัด</a><a href="#" data-anchor="all-sources">เอกสารอ้างอิง</a>`;}
 else{const c=chapters[route.id-1];state.last=c.id;save();document.title=`${c.title} · Web Notes 01076119`;document.getElementById('breadcrumb').innerHTML=`<span>บทเรียน / </span><span>${c.title}</span>`;main.innerHTML=`<div class="print-only">01076119 · WEB APPLICATION DEVELOPMENT</div><div class="heading-row"><h1>${c.title}</h1><button class="btn subtle print" data-action="print">${icon('print')}<span>พิมพ์หน้านี้</span></button></div><p class="lead">${c.subtitle}</p><p class="source-badge">${escape(c.basis)}</p><nav class="tabs" aria-label="รูปแบบการทบทวน">${[['lesson','บทเรียน'],['tips','เทคนิคช่วยจำ'],['quiz','แบบทดสอบ 20 ข้อ']].map(([tab,label])=>`<a class="tab ${route.tab===tab?'active':''}" href="#/chapter/${c.id}/${tab}" ${route.tab===tab?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div id="chapter-content">${route.tab==='lesson'?lesson(c):route.tab==='tips'?tips(c):quiz(c)}</div>`;renderToc(c);}
 bindActions();wrapCode();bindAnchors();if(route.page==='chapter'&&route.tab==='lesson')observeSections();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
}
function lesson(c){return `<p class="code-reading-hint">ตัวอย่างโค้ดมีเลขบรรทัดและผลลัพธ์แยกไว้ กด “ขั้นถัดไป” เพื่อดูบรรทัดที่กำลังอธิบายและค่าที่เปลี่ยนระหว่างทาง อ่าน “ก่อนเริ่ม” เพื่อรู้ข้อมูล/ไฟล์ที่ต้องมี ผลลัพธ์เป็นตัวอย่างตามเงื่อนไขที่ระบุ ไม่ได้รันโค้ดหรือเรียก API จริงในหน้าเรียน</p>${c.sections.map((s,i)=>`<section id="section-${i}" class="article-section"><h2>${s.title}</h2>${s.body}</section>`).join('')}<details class="objectives"><summary>เมื่ออ่านจบ คุณควรทำอะไรได้บ้าง</summary><ul>${c.goals.map(g=>`<li>${g}</li>`).join('')}</ul></details><div class="chapter-actions"><button class="btn ${state.read.includes(c.id)?'':'primary'}" data-action="read">${icon('check')}${state.read.includes(c.id)?'อ่านบทนี้แล้ว · ยกเลิกเครื่องหมาย':'ทำเครื่องหมายว่าอ่านแล้ว'}</button><a class="btn" href="#/chapter/${c.id}/quiz">ทดสอบความเข้าใจ 20 ข้อ</a></div>${sourceHTML(c)}<div class="next-chapter">${c.id>1?`<a href="#/chapter/${c.id-1}/lesson">← ${chapters[c.id-2].title}</a>`:'<span></span>'}${c.id<chapters.length?`<a href="#/chapter/${c.id+1}/lesson">${chapters[c.id].title} →</a>`:'<a href="#/overview">กลับภาพรวมวิชา →</a>'}</div>`;}
function tips(c){return `<h2>จำหลักการ แล้วลองอธิบายด้วยตัวเอง</h2><p class="muted">อ่านหนึ่งประเด็น ปิดคำอธิบาย แล้วลองยกตัวอย่างที่ต่างจากในสไลด์</p>${c.tips.map(([title,text],i)=>`<section class="tip-item" id="tip-${i}"><span class="tip-index">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${text}</p></div></section>`).join('')}<details class="retrieval"><summary>วิธีทบทวนแบบ Active Recall</summary><p>เขียนคำตอบโดยไม่เปิดบทเรียน → อธิบายให้เพื่อนฟัง → ลองรันตัวอย่างที่เปลี่ยน input → กลับตรวจจุดที่ผิด แล้วทบทวนอีกครั้งในวันถัดไป อย่าจำเพียงตัวเลือกของข้อสอบ ให้บอกเหตุผลว่าทำไมตัวเลือกอื่นผิดด้วย</p></details><a class="btn primary" href="#/chapter/${c.id}/quiz">ลองทำแบบทดสอบ 20 ข้อ</a>${sourceHTML(c)}`;}
function attempt(c){let a=state.attempts[c.id];if(!a||!Array.isArray(a.ids)||!a.ids.length||a.ids.some(id=>!c.quiz.some(q=>q.id===id))||!a.answers||typeof a.answers!=='object'){a={ids:c.quiz.map(q=>q.id),answers:{},submitted:false};state.attempts[c.id]=a;}return a;}
function questions(c,a){return a.ids.map(id=>c.quiz.find(q=>q.id===id));}
function selectedAnswers(q,a){
 const raw=a.answers[q.id];
 const values=Array.isArray(raw)?raw:Number.isInteger(raw)?[raw]:[];
 return [...new Set(values.filter(x=>Number.isInteger(x)&&x>=0&&x<q.options.length))].sort((a,b)=>a-b);
}
function isCorrect(q,a){const chosen=selectedAnswers(q,a);return chosen.length===q.answers.length&&chosen.every(x=>q.answers.includes(x));}
function result(c,a){const qs=questions(c,a);return {total:qs.length,answered:qs.filter(q=>selectedAnswers(q,a).length>0).length,score:qs.filter(q=>isCorrect(q,a)).length,wrong:qs.filter(q=>!isCorrect(q,a)).map(q=>q.id)};}
function quiz(c){const a=attempt(c),r=result(c,a);return `<div id="quiz-status">${quizStatus(c,a,r)}</div><form id="quiz-form" aria-label="แบบทดสอบบท ${c.id}">${questions(c,a).map((q,i)=>questionHTML(q,i,a)).join('')}</form>${a.submitted?'':`<button class="btn primary" data-action="grade">ตรวจคำตอบ</button><p class="quiz-footer">เฉลยพร้อมเหตุผลและเทคนิคจำจะแสดงหลังตรวจคำตอบ · บันทึกคำตอบในเบราว์เซอร์นี้โดยอัตโนมัติ</p>`}`;}
function quizStatus(c,a,r){if(a.submitted)return `<section class="quiz-status quiz-result" tabindex="-1"><h2>${a.ids.length===20?'ผลการทบทวนบทนี้':'ผลรอบแก้ตัว'}</h2><div class="score-number">${r.score} <small>/ ${r.total} คะแนน</small></div><p>${r.score===r.total?'เข้าใจครบทุกข้อในรอบนี้ ลองอธิบายเหตุผลด้วยภาษาของตัวเองอีกครั้ง':`ตอบถูก ${r.score} ข้อ · ผิดหรือเว้นว่าง ${r.total-r.score} ข้อ · อ่านเหตุผลและทบทวนจุดที่พลาดด้านล่าง`}</p><button class="btn primary" data-action="restart">ทำใหม่ครบ 20 ข้อ</button>${r.wrong.length?'<button class="btn" data-action="retry-wrong">ทำเฉพาะข้อที่ผิด</button>':''}<a class="btn" href="#/chapter/${c.id}/lesson">กลับอ่านบทเรียน</a></section>`;
return `<section class="quiz-status"><h2>${a.ids.length===20?'แบบทดสอบ 20 ข้อ':'ทบทวนเฉพาะข้อที่ผิด'}</h2><p>แต่ละบทมี 16 ข้อเลือกคำตอบเดียว (วงกลม) และ 4 ข้อเลือกหลายคำตอบ (ช่องสี่เหลี่ยม) ข้อละ 1 คะแนน แบบหลายคำตอบต้องเลือกถูกครบและไม่เลือกเกิน ไม่มีคะแนนบางส่วนหรือคะแนนติดลบ ทำครบแล้วกดตรวจคำตอบ</p><div class="quiz-controls"><div class="quiz-progress"><span><strong id="answer-count">${r.answered} / ${r.total}</strong> ตอบแล้ว</span><progress id="answer-progress" value="${r.answered}" max="${r.total}" aria-label="ตอบแล้ว ${r.answered} จาก ${r.total} ข้อ"></progress></div><button class="btn primary" data-action="grade">ตรวจคำตอบ</button></div><p class="status-message" id="quiz-warning" role="status"></p></section>`;}
function questionHTML(q,i,a){
 const selected=selectedAnswers(q,a),done=a.submitted,correct=isCorrect(q,a),multi=q.type==='multiple';
 return `<fieldset class="question" id="q-${q.id}"><legend>${i+1}. ${escape(q.question)} <span class="question-kind">${multi?'เลือกหลายคำตอบ':'เลือกคำตอบเดียว'}</span></legend><div>${q.options.map((option,j)=>`<label class="answer ${selected.includes(j)?'selected':''} ${done&&q.answers.includes(j)?'correct':''} ${done&&selected.includes(j)&&!q.answers.includes(j)?'incorrect':''}"><input type="${multi?'checkbox':'radio'}" name="q-${q.id}" value="${j}" ${selected.includes(j)?'checked':''} ${done?'disabled':''}><span class="letter">${'ABCD'[j]}</span><span>${escape(option)}</span>${done&&(q.answers.includes(j)||selected.includes(j))?`<span class="answer-tag">${q.answers.includes(j)?'คำตอบที่ถูก':'ที่คุณเลือก'}</span>`:''}</label>`).join('')}</div>${done?`<div class="explanation"><p class="${correct?'right':'wrong'}"><strong>${correct?'ตอบถูก':selected.length?'ยังไม่ถูก':'เว้นว่าง'} · เฉลย ${q.answers.map(n=>'ABCD'[n]).join(', ')}</strong></p><p>${escape(q.explanation)}</p><p class="memory"><strong>จำให้เข้าใจ:</strong> ${escape(q.tip)}</p></div>`:''}</fieldset>`;
}
function renderToc(c){const toc=document.getElementById('toc');if(route.tab==='quiz'){const a=attempt(c);toc.innerHTML=`<h3>ไปยังข้อที่</h3><div class="question-map">${questions(c,a).map((q,i)=>`<a href="#" data-anchor="q-${q.id}" data-qid="${q.id}" class="${a.submitted&&!isCorrect(q,a)?'wrong':selectedAnswers(q,a).length?'answered':''}" aria-label="ข้อ ${i+1}${a.submitted?(isCorrect(q,a)?' ตอบถูก':' ผิดหรือเว้นว่าง'):''}">${i+1}</a>`).join('')}</div><p class="small-meta">ทั้งหมด ${a.ids.length} ข้อ<br>ตรวจแล้วจึงแสดงเฉลย</p>`;}else{const items=route.tab==='lesson'?c.sections:c.tips.map(([title])=>({title}));toc.innerHTML=`<h3>ในหน้านี้</h3>${items.map((s,i)=>`<a href="#" data-anchor="${route.tab==='lesson'?'section':'tip'}-${i}">${s.title}</a>`).join('')}<p class="small-meta">อ่านประมาณ ${c.minutes} นาที<br>${c.sources.length} PDF · ${(c.refs||[]).length+(refs[c.id]||[]).length} เอกสารอ้างอิง · แบบฝึก 20 ข้อ</p>`;}}
function readinessHTML(){
 const completed=chapters.filter(c=>Number.isFinite(state.fullResults[c.id]?.score));
 const strong=completed.filter(c=>state.fullResults[c.id].score>=16);
 const needs=completed.filter(c=>state.fullResults[c.id].score<16);
 return `<section id="readiness" class="article-section readiness"><h2>พร้อมสอบหรือยัง?</h2><p><strong>ก่อนเติม: เนื้อหาเดิมยังไม่ครบ Scope_2026A</strong> โดยขาดบทตรงเรื่อง runtime/npm, layout, Date/Time, errors, frameworks และ project setup ขณะนี้เพิ่มบทนำและแบบฝึกเชื่อมครบ ${Course.scope.length} หัวข้อแล้ว แต่ยังต้องเทียบความลึกและเวอร์ชันกับ document อาจารย์ที่ยังไม่ได้รับ</p><div class="readiness-summary"><strong>${strong.length} / ${chapters.length}</strong><span>บทที่รอบเต็มล่าสุดได้อย่างน้อย 16/20</span></div><p>ทำรอบเต็มแล้ว ${completed.length} บท · ยังไม่มีผล ${chapters.length-completed.length} บท · ควรทบทวนเพิ่ม ${needs.length} บท</p><p class="muted">80% เป็นเป้าฝึกที่ตั้งไว้ในเว็บ ไม่ใช่เกณฑ์ผ่านวิชาหรือการรับประกันคะแนนสอบ ใช้ผลรอบเต็มล่าสุด ไม่ใช้คะแนนสูงสุดหรือรอบแก้ตัว และเครื่องหมายอ่านแล้วไม่ใช่หลักฐานความเข้าใจ</p>${needs.length?`<p>ทบทวนก่อน: ${needs.map(c=>`<a href="#/chapter/${c.id}/lesson">บท ${c.id} ${escape(c.title)}</a>`).join(' · ')}</p>`:''}<ol><li>ทำแต่ละบทโดยไม่เปิดเฉลย แล้วอธิบายเหตุผลของตัวเลือกที่ผิดได้</li><li>ลองเปลี่ยน input/โค้ดในโจทย์และทำนายผลใหม่ แทนจำตำแหน่งตัวเลือก</li><li>ทบทวนจุดผิดและทำรอบเต็มอีกครั้งหลังเว้นระยะ</li><li>เมื่อได้ document อาจารย์ ให้ตรวจ router/version และหัวข้อย่อย โดยเฉพาะ React, Next.js, Express และ npm</li></ol></section>`;
}
function overview(){
 const total=chapters.reduce((n,c)=>n+c.quiz.length,0),pages=Course.sources.reduce((n,s)=>n+s[1],0);
 return `<div class="heading-row"><h1>การพัฒนาโปรแกรมบนเว็บ</h1><button class="btn subtle print" data-action="print">${icon('print')}<span>พิมพ์หน้านี้</span></button></div><p class="lead">01076119 · ทบทวนตาม Scope_2026A<br>บทเรียนภาษาไทย พร้อมโจทย์อ่านโค้ดและเฉลยเหตุผล</p><div class="overview-stats"><div><strong>${chapters.length}</strong><span>บทเรียน</span></div><div><strong>${total}</strong><span>ข้อฝึก · บทละ 20 ข้อ</span></div><div><strong>${Course.scope.length}</strong><span>หัวข้อในขอบเขตสอบ</span></div></div>${quizUpdated?'<p class="note">ปรับชุดข้อสอบเป็นแบบคำตอบเดียวและหลายคำตอบแล้ว รอบเก่าเก็บแยกไว้ในข้อมูลเครื่องและไม่นำมาประเมินชุดใหม่ เครื่องหมายอ่านแล้วยังคงอยู่</p>':''}<div class="chapter-actions"><a class="btn primary" href="#/chapter/${state.last>=1&&state.last<=chapters.length?state.last:1}/lesson">อ่านต่อจากบทล่าสุด</a><a class="btn" href="#/chapter/1/quiz">เริ่มแบบทดสอบบท 1</a></div>${readinessHTML()}<section id="scope-map" class="article-section"><h2>เทียบ Scope ทีละหัวข้อ</h2><p>ถอดรายการจาก <a href="${assetUrl('sources/Scope_2026A.pdf')}" target="_blank" rel="noopener">Scope_2026A.pdf หน้า 1</a> มี 24 หัวข้อย่อย เลขลำดับในต้นฉบับซ้ำบางส่วน จึงเทียบตามชื่อหัวข้อ · ตรวจเมื่อ ${Course.reviewed}</p><p class="note">ตารางนี้รายงานความครอบคลุมของสื่อ ไม่ใช่การยืนยันความพร้อมของผู้เรียน บทเสริมจากเอกสารทางการยังต้องตรวจเทียบกับเอกสารเฉพาะของอาจารย์ในภายหลัง</p><div class="table-scroll" tabindex="0" role="region" aria-label="ตารางเทียบขอบเขตสอบ เลื่อนแนวนอนได้"><table class="scope-table"><thead><tr><th scope="col">หัวข้อใน Scope</th><th scope="col">ก่อนเติม</th><th scope="col">สิ่งที่เพิ่ม / ตรวจ</th><th scope="col">อ่านบท</th></tr></thead><tbody>${Course.scope.map(([key,group,title,ids,before,after])=>`<tr><th scope="row"><small>${escape(group)}</small>${escape(title)}</th><td>${escape(before)}</td><td>${escape(after)}</td><td>${ids.map(id=>`<a href="#/chapter/${id}/lesson">${id}</a>`).join(' · ')}</td></tr>`).join('')}</tbody></table></div><p><strong>ลำดับอ่านแนะนำ:</strong> 1-3 → 12 → 4-9 → 11 → 10 → 13-20 โดยอ่านซ้ำเฉพาะบทที่ยังอธิบายหลักการไม่ได้</p></section><h2 id="chapters">บทเรียนทั้งหมด</h2><div class="overview-list">${chapters.map(c=>`<a class="chapter-row" href="#/chapter/${c.id}/lesson"><span class="row-number">${String(c.id).padStart(2,'0')}</span><div><h3>${c.title}</h3><p>${c.subtitle}</p><small>${c.id>10?'เสริมจากเอกสารทางการ':'PDF + คำอธิบายเสริม'}</small></div><span class="row-meta">${state.read.includes(c.id)?'✓ อ่านแล้ว':'ยังไม่ทำเครื่องหมาย'}<br>${Number.isFinite(state.best[c.id])?`สูงสุด ${state.best[c.id]} / 20`:'แบบทดสอบ 20 ข้อ'}<br>${Number.isFinite(state.fullResults[c.id]?.score)?`รอบเต็มล่าสุด ${state.fullResults[c.id].score} / 20`:''}</span></a>`).join('')}</div><section id="course-scope" class="article-section"><h2>วิธีใช้และสิ่งที่ยังต้องยืนยัน</h2><ol><li>อ่านบทเรียน ตัวอย่าง และแหล่งอ้างอิงท้ายบท</li><li>ทบทวนแท็บเทคนิคช่วยจำแล้วทำข้อสอบ 16 ข้อคำตอบเดียว + 4 ข้อหลายคำตอบ</li><li>ข้อหลายคำตอบต้องเลือกถูกครบ ไม่เลือกเกิน จึงได้ 1 คะแนน ไม่มีคะแนนบางส่วน</li><li>อ่านเฉลยและทำเฉพาะข้อที่ผิดได้ รอบแก้ตัวไม่เปลี่ยนผลรอบเต็มหรือคะแนนสูงสุด</li></ol><p>ยังไม่ทราบ document ที่อาจารย์จะส่ง, router/version ของ frameworks, สัดส่วนคะแนน และระดับความลึกของแต่ละหัวข้อ แบบฝึกทั้งหมดเขียนใหม่ ไม่ใช่ข้อสอบจริง ไม่ทราบว่าในข้อสอบจริงจะมีแบบหลายคำตอบหรือไม่ จึงเพิ่มเป็นเครื่องมือฝึกแยกตามป้ายทุกข้อ</p><p>Tailwind และ MVC ไม่ได้อยู่ในรายการ Scope_2026A ฉบับนี้ จึงไม่จัดเป็นบทบังคับ แม้ปรากฏในคำอธิบายเดิมบางส่วน บท Next.js ใช้ App Router; Express ระบุข้อแตกต่าง 4/5 ชัดเจน</p><p>คำตอบและความคืบหน้าอยู่ใน localStorage ของ browser นี้ ไม่ซิงก์ข้ามเครื่อง การล้างข้อมูลเว็บอาจทำให้ข้อมูลหาย</p><button class="btn danger" data-action="reset-progress">ล้างความคืบหน้าและคำตอบในเครื่องนี้</button><p id="reset-confirm" hidden>ลบข้อมูลทบทวนเฉพาะ browser นี้ <button class="btn danger" data-action="confirm-reset">ยืนยันล้างข้อมูล</button> <button class="btn" data-action="cancel-reset">ยกเลิก</button></p></section><section id="all-sources" class="article-section"><h2>เอกสารอ้างอิง</h2><p class="muted">${Course.sources.length} PDF รวม ${pages} หน้า (15 ไฟล์เดิม + Scope_2026A ที่แนบครั้งนี้) · เอกสารต้นฉบับไม่ถูกแก้ไข</p><ol class="source-list">${Course.sources.map(([file,pages])=>`<li><a href="${assetUrl('sources/'+encodeURIComponent(file))}" target="_blank" rel="noopener">${escape(file)}</a> <small>· ${pages} หน้า</small></li>`).join('')}</ol><p>บท 11-20 ใช้เอกสารทางการ MDN, Node.js, npm, SemVer, React, Next.js, Express, Git และ GitHub ลิงก์เฉพาะเรื่องอยู่ท้ายแต่ละบท เอกสารออนไลน์ต้องใช้อินเทอร์เน็ต แต่บทเรียนและแบบฝึกอ่านออฟไลน์ได้เมื่อมีไฟล์เว็บครบ</p></section>`;
}
function handleAnswerChange(c,e){
 if(!e.target.matches('input[type=radio],input[type=checkbox]'))return;
 const a=attempt(c);if(a.submitted)return;
 const qid=e.target.name.slice(2),q=c.quiz.find(q=>q.id===qid);if(!q)return;
 const field=e.target.closest('.question');
 a.answers[qid]=Array.from(field.querySelectorAll('input:checked'),input=>Number(input.value));save();
 field.querySelectorAll('.answer').forEach(label=>label.classList.toggle('selected',label.querySelector('input').checked));
 const r=result(c,a);document.getElementById('answer-count').textContent=`${r.answered} / ${r.total}`;
 const bar=document.getElementById('answer-progress');bar.value=r.answered;bar.setAttribute('aria-label',`ตอบแล้ว ${r.answered} จาก ${r.total} ข้อ`);
 document.querySelector(`[data-qid="${qid}"]`)?.classList.toggle('answered',selectedAnswers(q,a).length>0);
 incompleteConfirmed=false;document.getElementById('quiz-warning').textContent='';
}
function bindActions(){
 document.getElementById('main').addEventListener('click',onAction);
 document.getElementById('quiz-form')?.addEventListener('change',e=>handleAnswerChange(chapters[route.id-1],e));
}
function onAction(e){const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();const action=button.dataset.action;if(action==='print'){window.print();return;}if(action==='reset-progress'){document.getElementById('reset-confirm').hidden=false;return;}if(action==='cancel-reset'){document.getElementById('reset-confirm').hidden=true;return;}if(action==='confirm-reset'){state={read:[],best:{},attempts:{},fullResults:{},last:1,quizRevision:Course.revision};quizUpdated=false;save();render();toast('ล้างข้อมูลทบทวนในเครื่องนี้แล้ว');return;}const c=chapters[route.id-1];if(action==='read'){state.read=state.read.includes(c.id)?state.read.filter(id=>id!==c.id):[...state.read,c.id];save();button.innerHTML=`${icon('check')}${state.read.includes(c.id)?'อ่านบทนี้แล้ว · ยกเลิกเครื่องหมาย':'ทำเครื่องหมายว่าอ่านแล้ว'}`;button.classList.toggle('primary',!state.read.includes(c.id));document.getElementById('nav').innerHTML=navHTML();document.querySelector('.nav-footer').innerHTML=progressHTML();toast(state.read.includes(c.id)?'บันทึกว่าอ่านบทนี้แล้ว':'ยกเลิกเครื่องหมายอ่านแล้ว');return;}
 if(action==='grade'){const a=attempt(c);if(a.submitted)return;const r=result(c,a);if(r.answered<r.total&&!incompleteConfirmed){incompleteConfirmed=true;const warning=document.getElementById('quiz-warning');warning.innerHTML=`ยังไม่ได้ตอบ ${r.total-r.answered} ข้อ หากตรวจตอนนี้ข้อว่างจะนับเป็นผิด <button class="btn" data-action="grade">ตรวจโดยนับข้อว่างเป็นผิด</button>`;warning.scrollIntoView({block:'center',behavior:'smooth'});return;}a.submitted=true;if(a.ids.length===c.quiz.length){state.best[c.id]=Math.max(state.best[c.id]||0,r.score);state.fullResults[c.id]={score:r.score,total:r.total,revision:Course.revision};}save();refreshQuiz(c);return;}
 if(action==='restart'||action==='retry-wrong'){const old=attempt(c);const ids=action==='restart'?c.quiz.map(q=>q.id):result(c,old).wrong;if(!ids.length)return;state.attempts[c.id]={ids,answers:{},submitted:false};save();refreshQuiz(c);}
}
function refreshQuiz(c){
 incompleteConfirmed=false;document.getElementById('chapter-content').innerHTML=quiz(c);renderToc(c);
 document.getElementById('quiz-form')?.addEventListener('change',e=>handleAnswerChange(c,e));
 bindAnchors();document.getElementById('quiz-status').scrollIntoView({block:'start',behavior:'instant'});document.querySelector('.quiz-result')?.focus({preventScroll:true});
}
function bindAnchors(){document.querySelectorAll('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.anchor)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});}
function observeSections(){observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){document.querySelectorAll('#toc a').forEach(a=>a.classList.toggle('current',a.dataset.anchor===entry.target.id));}}, {rootMargin:'-80px 0px -65% 0px'});document.querySelectorAll('.article-section').forEach(el=>observer.observe(el));}
function wrapCode(){document.querySelectorAll('#main pre').forEach((pre,index)=>{
 const rawCode=pre.textContent;
 const wrap=document.createElement('div');wrap.className='code-wrap';pre.before(wrap);wrap.append(pre);
 const button=document.createElement('button');button.className='copy-code';button.textContent='คัดลอก';button.setAttribute('aria-label','คัดลอกโค้ดต้นฉบับโดยไม่มีเลขบรรทัด');
 button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(rawCode);button.textContent='คัดลอกแล้ว';setTimeout(()=>button.textContent='คัดลอก',1800);}catch{
  const field=document.createElement('textarea');field.value=rawCode;field.setAttribute('aria-label','โค้ดต้นฉบับสำหรับคัดลอก');field.className='copy-fallback';wrap.append(field);field.select();
  let copied=false;try{copied=document.execCommand('copy');}catch{}
  if(copied){field.remove();toast('คัดลอกโค้ดแล้ว');}else{toast('เลือกโค้ดต้นฉบับแล้ว กด Ctrl+C หรือคัดลอกด้วยเมนูเบราว์เซอร์');field.addEventListener('blur',()=>field.remove(),{once:true});}
 }});wrap.append(button);
 if(route.page==='chapter'&&route.tab==='lesson')window.enhanceLessonCode?.(wrap,pre,rawCode,route.id+'-'+(index+1));
});
const flow=document.querySelector('.flow');if(flow){const boxes=flow.querySelectorAll('span');boxes[0]?.insertAdjacentHTML('afterbegin','<svg class="flow-icon" viewBox="0 0 32 32" aria-hidden="true"><rect x="3" y="4" width="26" height="24" rx="4"/><path d="M3 11h26M8 7h1m3 0h1"/></svg>');boxes[1]?.insertAdjacentHTML('afterbegin','<svg class="flow-icon" viewBox="0 0 32 32" aria-hidden="true"><rect x="4" y="3" width="24" height="10" rx="3"/><rect x="4" y="19" width="24" height="10" rx="3"/><path d="M9 8h2m-2 16h2M16 8h7m-7 16h7M10 13v6m12-6v6"/></svg>');flow.querySelector('b').outerHTML='<div class="flow-arrows">HTTP Request<svg viewBox="0 0 100 20" aria-hidden="true"><path d="M2 10h93m-6-5 6 5-6 5"/></svg><svg viewBox="0 0 100 20" aria-hidden="true"><path d="M98 10H5m6-5-6 5 6 5"/></svg>HTTP Response</div>';const note=document.createElement('p');note.className='note';note.innerHTML='<strong>จำง่าย:</strong> HTML = โครงสร้าง · CSS = หน้าตา · JavaScript = พฤติกรรม';flow.closest('.article-section').append(note);}}
const searchIndex=chapters.flatMap(c=>c.sections.map((s,i)=>{const div=document.createElement('div');div.innerHTML=s.body;return {chapter:c,title:s.title,index:i,text:div.textContent.replace(/\s+/g,' ')};}));
function search(){const query=document.getElementById('search').value.trim().toLowerCase();const box=document.getElementById('search-results');box.hidden=!query;if(!query)return;const hits=searchIndex.filter(x=>(x.chapter.title+' '+x.title+' '+x.text).toLowerCase().includes(query)).slice(0,12);box.innerHTML=hits.length?hits.map(x=>{const at=x.text.toLowerCase().indexOf(query),start=Math.max(0,at-35),snippet=x.text.slice(start,start+130);return `<a href="#/chapter/${x.chapter.id}/lesson" data-search-chapter="${x.chapter.id}" data-search-section="${x.index}"><strong>บท ${x.chapter.id} · ${escape(x.title)}</strong><small>${escape(snippet)}…</small></a>`;}).join(''):'<p>ไม่พบเนื้อหาที่ตรงกัน ลองใช้คำสั้น เช่น HTTP, array หรือ ตัวแปร</p>';box.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{const id=Number(a.dataset.searchChapter),index=a.dataset.searchSection;box.hidden=true;const targetHash=`#/chapter/${id}/lesson`;if(location.hash===targetHash){document.getElementById(`section-${index}`)?.scrollIntoView({block:'start'});}else{window.addEventListener('hashchange',()=>setTimeout(()=>document.getElementById(`section-${index}`)?.scrollIntoView({block:'start'}),0),{once:true});}}));}
shell();document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main').focus();window.scrollTo({top:0,behavior:'instant'});});window.addEventListener('hashchange',render);if(!location.hash)history.replaceState(null,'','#/overview');render();
})();
